#!/usr/bin/env bash
set -euo pipefail
BASE=9fd2a0547c3d56306d5edf471264221c71f4b000
if [ -f ./.env ]; then set -a; . ./.env; set +a; fi
cd /opt/albert-scott && git rev-parse --verify origin/master >/dev/null && ! grep -q '4GB box' docs/do-it/DO-IT.md && /usr/bin/python3 -c 'import re;t=open("docs/do-it/DO-IT.md",encoding="utf-8").read();L=t.split("\n");P="> **Status (2026-10-15):**";assert len([l for l in L if l.startswith(P)])==4,"status line count";assert L[2].startswith("**Version:**") and L[3]=="" and L[4].startswith(P) and L[5]=="","banner placement";B=L[4];bad=[p for p in ("DO-IT V2","2026-09-20","L-spec-NNNN","L-card","L-charter","github.com/fredhead88/do-it-ledger","`do-it-ledger` skill","`~/.claude/ledger/<NNN>-*.yml`","~/.do-it","spec-pending-review","inbound-spec","/orc","single source of truth","always current","v4 operating description","7b-7e","as of 2026-10-15 live read") if p not in B];assert not bad,bad;n=lambda h:[k for k,l in enumerate(L) if l.startswith(h)][0];assert all(L[n(h)+1]=="" and L[n(h)+2].startswith(P) and L[n(h)+3]=="" and all(p in L[n(h)+2] for p in ps) for h,ps in (("## 0. CONFIG",("~/.do-it","`do-it-ledger` skill")),("## 1. The map",("/orc","2026-09-20")),("## 3. The index",("L-spec-NNNN","~/.claude/ledger")))),"section notices"' && /usr/bin/python3 -c 'import re;L=open("docs/do-it/DO-IT.md",encoding="utf-8").read().split("\n");i=[k for k,l in enumerate(L) if l.startswith("- **Throughput via parallelism.**")][0];j=next(k for k in range(i+1,len(L)) if L[k].startswith("- **"));bl=L[i:j];bad=[p for p in ("[seats] builder","/home/albert/.do-it/models.toml","as of 2026-10-15 live read") if not any(p in l for l in bl)];assert not bad and not any("4GB box" in l for l in bl),bad;T=" ".join(bl);PH="as of 2026-10-15 live read";ps=T.find(PH);pe=ps+len(PH);se=lambda s:re.search(r"[.!?](\s|$)",s);assert any((pe<=m.start()<=pe+40 and not se(T[pe:m.start()])) or (ps-40<=m.end()<=ps and not se(T[m.end():ps])) for m in re.finditer(r"\b12\b",T)),"12 adjacency"' && base="$BASE" && test "$(git diff --name-only "$base" | tr -d '\n')" = "docs/do-it/DO-IT.md" && /usr/bin/python3 -c 'import re,sys,subprocess as s;b=sys.argv[1];f="docs/do-it/DO-IT.md";o=s.check_output(["git","show",b+":"+f],text=True).split("\n");d=s.check_output(["git","diff","-U0",b,"--",f],text=True);ix=lambda h:[k+1 for k,l in enumerate(o) if l.startswith(h)][0];ok={(3,0),(4,0)}|{(ix(h)+j,0) for h in ("## 0. CONFIG","## 1. The map","## 3. The index") for j in (0,1)};r=ix("- **Throughput via parallelism.**");hs=[(int(m.group(1)),int(m.group(2) or 1)) for m in re.finditer(r"(?m)^@@ -(\d+)(?:,(\d+))? \+\d+(?:,\d+)? @@",d)];ins=[h for h in hs if h[1]==0];ch=[h for h in hs if h[1]>0];assert len(ins)==4 and all(h in ok for h in ins) and 1<=len(ch)<=2 and all(r<=s and s+c-1<=r+2 for s,c in ch) and sum(c for s,c in ch)<=2,hs' "$base" && echo VERIFY_OK
